import{_ as a,o,c as e,a4 as r}from"./chunks/framework.BRzJ4ijD.js";const _=JSON.parse('{"title":"时钟与顺序","description":"","frontmatter":{},"headers":[],"relativePath":"distributed/clock/index.md","filePath":"distributed/clock/README.md","lastUpdated":1788475713000}'),i={name:"distributed/clock/index.md"};function l(n,t,c,s,d,p){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="时钟与顺序" tabindex="-1">时钟与顺序 <a class="header-anchor" href="#时钟与顺序" aria-label="Permalink to &quot;时钟与顺序&quot;">​</a></h1><p>时钟与顺序是分布式系统的走廊——&quot;在分布式系统中, you cannot totally order events without coordinating&quot; 是 Lamport 1978 的奠基论断。 多节点无 wall clock 同步, 还能<strong>怎么知道谁先, 谁后, 谁并发</strong>？ 三大轴心:</p><ol><li><strong>逻辑时钟 (Lamport Clock)</strong>: 单调自增 + 消息捎带, 给 events 一个 transitive partial order。Lamport 1978。</li><li><strong>向量时钟 (Vector Clock, Mattern 1989 / Fidge 1988)</strong>: N 维 count array 在节点间传播, 精确检测 concurrency vs causal order。</li><li><strong>混合时钟 (HLC, Kulkarni 2014) + 物理时钟 (TrueTime, Spanner 2012)</strong>: 给&quot;事件&quot;带上 wall-clock-approximate 时间, 同时保持因果序。 CockroachDB / YugaByte / TiDB 用 HLC; Google Spanner 用 GPS+原子钟提供 TrueTime。</li></ol><p>DAG (有向无环图) 是顺序的另一种一般化: git commit / blockchain / IPFS DAG / Bitcoin block chain 都隐含 partial order, 用 hash chaining + tip selection 算法给出 consensus view.</p><ul><li><a href="./logical">逻辑时钟、向量时钟、HLC</a></li><li><a href="./physical">TrueTime / HLC / attestation</a></li><li><a href="./dag">DAG、git、blockchain 的序</a></li></ul>',5)])])}const h=a(i,[["render",l]]);export{_ as __pageData,h as default};
